{
  "name": "extract_sales_objectives",
  "description": "Extracts sales objectives, requirements, and key information from RFP text. Analyzes the document to identify client details, project scope, deliverables, timelines, budget constraints, and categorizes requirements into technical, business, and functional categories.",
  "tool_type": "api",
  "schema": {
    "type": "function",
    "function": {
      "name": "extract_sales_objectives",
      "description": "Extracts sales objectives, requirements, and key information from RFP text",
      "parameters": {
        "type": "object",
        "properties": {
          "rfp_text": {
            "type": "string",
            "description": "The complete RFP document text to analyze"
          }
        },
        "required": ["rfp_text"]
      }
    }
  },
  "code": "http://localhost:8080/api/extract-sales-objectives"
}

{
  "name": "match_sku",
  "description": "Matches search terms with available SKUs using fuzzy matching. Returns top matching SKUs with similarity scores, including SKU code, name, description, category, and price.",
  "tool_type": "api",
  "schema": {
    "type": "function",
    "function": {
      "name": "match_sku",
      "description": "Matches search terms with available SKUs using fuzzy matching",
      "parameters": {
        "type": "object",
        "properties": {
          "search_term": {
            "type": "string",
            "description": "The product or service to search for"
          },
          "top_n": {
            "type": "integer",
            "description": "Number of top matches to return (default: 5)",
            "default": 5
          }
        },
        "required": ["search_term"]
      }
    }
  },
  "code": "http://localhost:8080/api/match-sku"
}

{
  "name": "validate_sku",
  "description": "Validates if a SKU exists and returns its complete details including code, name, description, category, and price.",
  "tool_type": "api",
  "schema": {
    "type": "function",
    "function": {
      "name": "validate_sku",
      "description": "Validates if a SKU exists and returns its details",
      "parameters": {
        "type": "object",
        "properties": {
          "sku_code": {
            "type": "string",
            "description": "The SKU code to validate"
          }
        },
        "required": ["sku_code"]
      }
    }
  },
  "code": "http://localhost:8080/api/validate-sku"
}

{
  "name": "calculate_total_cost",
  "description": "Calculates the total cost for a list of SKUs including quantities, taxes, and discounts. Returns subtotal, tax amount, discount amount, and grand total.",
  "tool_type": "api",
  "schema": {
    "type": "function",
    "function": {
      "name": "calculate_total_cost",
      "description": "Calculates total cost including taxes and discounts",
      "parameters": {
        "type": "object",
        "properties": {
          "skus": {
            "type": "array",
            "description": "List of SKU items with code and quantity",
            "items": {
              "type": "object",
              "properties": {
                "sku_code": {"type": "string"},
                "quantity": {"type": "integer"}
              },
              "required": ["sku_code", "quantity"]
            }
          },
          "tax_rate": {
            "type": "number",
            "description": "Tax rate as percentage (default: 18.0)",
            "default": 18.0
          },
          "discount_rate": {
            "type": "number",
            "description": "Discount rate as percentage (default: 0.0)",
            "default": 0.0
          }
        },
        "required": ["skus"]
      }
    }
  },
  "code": "http://localhost:8080/api/calculate-total-cost"
}

{
  "name": "generate_pricing_table",
  "description": "Generates a formatted pricing table with SKU details, quantities, unit prices, and totals. Returns HTML table ready for inclusion in proposals.",
  "tool_type": "api",
  "schema": {
    "type": "function",
    "function": {
      "name": "generate_pricing_table",
      "description": "Generates formatted pricing table",
      "parameters": {
        "type": "object",
        "properties": {
          "items": {
            "type": "array",
            "description": "List of items with SKU, name, quantity, price",
            "items": {
              "type": "object",
              "properties": {
                "sku": {"type": "string"},
                "name": {"type": "string"},
                "quantity": {"type": "integer"},
                "unit_price": {"type": "number"}
              },
              "required": ["sku", "name", "quantity", "unit_price"]
            }
          },
          "subtotal": {"type": "number"},
          "tax": {"type": "number"},
          "total": {"type": "number"}
        },
        "required": ["items", "subtotal", "tax", "total"]
      }
    }
  },
  "code": "http://localhost:8080/api/generate-pricing-table"
}

{
  "name": "format_proposal_html",
  "description": "Formats the complete proposal as professional HTML document. Includes executive summary, requirements, technical solutions, pricing, and terms. Returns complete HTML ready for presentation.",
  "tool_type": "api",
  "schema": {
    "type": "function",
    "function": {
      "name": "format_proposal_html",
      "description": "Formats complete proposal as HTML document",
      "parameters": {
        "type": "object",
        "properties": {
          "client_name": {"type": "string"},
          "project_title": {"type": "string"},
          "executive_summary": {"type": "string"},
          "requirements": {"type": "string"},
          "technical_solution": {"type": "string"},
          "pricing_table_html": {"type": "string"},
          "terms": {"type": "string"}
        },
        "required": ["client_name", "project_title", "executive_summary", "technical_solution", "pricing_table_html"]
      }
    }
  },
  "code": "http://localhost:8080/api/format-proposal-html"
}

